style.css:
@-moz-document domain("roblox.com") {
/* Fundo principal baseado na parede clássica do Talking Tom */
    body, 
    .content, 
    .container-main,
    .dark-theme,
    .gandalf-theme {
        background-color: #74b9ff !important; /* Azul celeste */
        background-image: linear-gradient(180deg, #74b9ff 0%, #a29bfe 100%) !important;
        color: #2d3436 !important;
        font-family: "Comic Sans MS", "Chalkboard SE", sans-serif !important;
    }

    /* Barra de navegação superior (estilo coleira/topo do app) */
    #header, 
    .navbar-inverse, 
    .rbx-header {
        background-color: #0984e3 !important; /* Azul escuro vivo */
        border-bottom: 5px solid #fdcb6e !important; /* Detalhe em amarelo ouro */
    }

    /* Modifica o texto da barra superior para branco */
    .rbx-header .text-header, .icon-nav, .rbx-navbar-link {
        color: #ffffff !important;
    }

    /* Cards de jogos e catálogo (estilo botões grandes e fofos do jogo) */
    .game-card-container, 
    .item-card, 
    .item-card-container, 
    .section-content,
    .left-col-container,
    .right-col-container {
        background-color: #ffffff !important;
        border-radius: 24px !important; /* Bordas super arredondadas infantis */
        border: 4px solid #00b894 !important; /* Borda verde-grama */
        box-shadow: 0px 8px 0px #006241 !important; /* Efeito de sombra 3D de desenho animado */
        transition: transform 0.1s ease !important;
    }

    /* Efeito de clique/hover nos cards (como se fossem botões do app) */
    .game-card-container:hover, 
    .item-card:hover {
        transform: scale(1.03) !important;
    }

    /* Botão de PLAY (Estilo o botão principal de iniciar/comida do Tom) */
    .btn-common-play-large, 
    .btn-to-play, 
    .btn-primary-md {
        background-color: #2ecc71 !important; /* Verde vibrante */
        border-radius: 30px !important;
        border: 4px solid #ffffff !important;
        box-shadow: 0px 6px 0px #27ae60 !important;
        color: white !important;
        font-weight: bold !important;
        text-shadow: 2px 2px 0px #1e7e43 !important;
    }

    .btn-common-play-large:hover, 
    .btn-primary-md:hover {
        background-color: #27ae60 !important;
        transform: translateY(2px) !important;
        box-shadow: 0px 4px 0px #1e7e43 !important;
    }

    /* Customização dos avatares (Arredondados como as bolhas do jogo) */
    .avatar-card-image, .avatar-headshot-img, .player-avatar-image {
        border-radius: 50% !important;
        border: 3px solid #0984e3 !important;
        background-color: #dfe6e9 !important;
    }

    /* Links de texto */
    a, .text-link {
        color: #d63031 !important; /* Vermelho desenho animado */
        font-weight: bold !important;
    }
    
    a:hover {
        color: #e17055 !important;
    }

    /* Remove anúncios para focar no visual limpo */
    .rbx-upgrade-now, 
    #AdvertisingLeaderboard, 
    .abp {
        display: none !important;
    }
}
